\begin{theorem}\label{nm:thm:oka-local}
For every disc $\Delta\Subset\cA$, the projection
$\pi_\Delta:\mathfrak X_\Delta\to\Delta$ is an Oka map. For every
$a\in\cA$, the manifold $X_a$ and both
$X_a\setminus S_{1,a}$ and $X_a\setminus S_{2,a}$ are Oka.
\end{theorem}

\begin{theorem}\label{thm:intro-point-modifications}
For every $a\in\cA$ and every finite set $P\subset X_a$ of distinct points,
both $X_a\setminus P$ and the simultaneous blow-up
$\operatorname{Bl}_P X_a$ are Oka.
\end{theorem}

\begin{proposition}
\label{prop:period-data-existence}
There are holomorphic functions
\[
 \tau,\mu,\beta_0:U\longrightarrow\C,
 \qquad \Im\tau>0,
\]
and holomorphic matrices $R_g:U\to\GL(2,\C)$ satisfying
\begin{align}
 R_{gh}(z)&=R_g(hz)R_h(z),
 \label{eq:R-cocycle}\\
 \Omega_a(gz)&=R_g(z)\Omega_a(z)A(g)^{-1}
 \label{eq:period-equivariance}
\end{align}
for every $g,h\in\Gamma$ and every $a\in\C$, where
\begin{equation}
\label{eq:period-matrix}
 \Omega_a(z)=
 \begin{pmatrix}
 6\mu(z)&\tau(z)&1&0\\
 \beta_0(z)+a&\mu(z)&0&1
 \end{pmatrix}.
\end{equation}
Let $t_c$ be the pullback to a sufficiently small lifted cusp neighbourhood
of Alp\"oge's local coordinate at $p_0$. There is a
holomorphic unit $u_1$ at $t_c=0$ such that
\begin{equation}
 \e^{2\pi\ii\tau}=t_cu_1(t_c).
 \label{eq:cusp-period-unit}
\end{equation}
After choosing a holomorphic logarithm of $u_1$, set
\begin{equation}
 h(t_c)=\frac{1}{2\pi\ii}\log u_1(t_c),
 \qquad s=\tau-h(t_c).
 \label{eq:cusp-corrected-period}
\end{equation}
Then $\e^{2\pi\ii s}=t_c$, and both $\mu$ and $\beta_0+\tau$ extend
holomorphically to $t_c=0$.

Set
\begin{equation}
\label{eq:D-a}
 \mathscr D_a(z)=\Im(\beta_0(z)+a)
        -\frac{6(\Im\mu(z))^2}{\Im\tau(z)}.
\end{equation}
The function $\mathscr D_0$ is
$\Gamma$-invariant, descends to $B\setminus\{p_0\}$, and tends to $-\infty$
as $p_0$ is approached.  Its descended function is continuous at the two
finite orbifold points; together with the cusp limit, this makes
$\mathscr D_0$ bounded above.
\end{proposition}

\begin{proposition}
\label{prop:admissible-half-plane}
Let
\[
 M_0=\sup_{z\in U}\mathscr D_0(z)<\infty.
\]
Then
\begin{equation}
\label{eq:admissible}
 \mathcal A:=\{a\in\C:\Im a<-M_0\}
\end{equation}
is a nonempty open half-plane, and for every $a\in\mathcal A$ the four columns
of $\Omega_a(z)$ are linearly independent over $\R$ for all $z\in U$.
\end{proposition}

\begin{lemma}
\label{lem:finite-free}
The biholomorphism $\widetilde g_j$ has order exactly $m_j$, and the action of
$\langle\widetilde g_j\rangle$ on $\mathcal P_{j,\Delta}$ is free.
\end{lemma}

\begin{lemma}
\label{lem:finite-conjugation}
On $\mathcal P_{j,\Delta}|_{\widetilde D_j^*\times\Delta}$ one has
\[
 h_j\widetilde g_jh_j^{-1}=\widetilde g_j^0,
 \qquad
 \widetilde g_j^0[z,\zeta,a]=[g_jz,R_{g_j}(z)\zeta,a].
\]
Consequently there is a jointly holomorphic biholomorphism
\begin{equation}
\label{eq:Gj}
 G_j:\mathcal N_{j,\Delta}|_{D_j^*\times\Delta}
 \xrightarrow{\ \cong\ }
 \mathcal J_\Delta|_{D_j^*\times\Delta}.
\end{equation}
\end{lemma}

\begin{definition}
\label{def:valid-cusp-cutoff}
Let $\Delta\Subset\mathcal A$ be a relatively compact parameter disc.  A
number $\varepsilon>0$ is called a \emph{valid cusp cutoff for $\Delta$} if
there exists a number $\varepsilon_1$ such that
\begin{enumerate}[label=\textup{(V\arabic*)}]
\item
\[
  0<\varepsilon<\varepsilon_1<\min\{1,\varepsilon_0\};
\]
\item with
\[
 M_C(\Delta,\varepsilon_1)
 =\sup_{\substack{|q|\le\varepsilon_1\\a\in\overline\Delta}}
   \bigl\|-2\pi\Im C_a(q)\bigr\|,
\]
one has
\begin{equation}
\label{eq:valid-cutoff-inequality}
 \frac{\|B_0^{-1}\|M_C(\Delta,\varepsilon_1)}
      {|\log\varepsilon|}\le\frac12;
\end{equation}
\item the closed subdisc $\overline D_\varepsilon=\{|q|\le\varepsilon\}$,
      viewed inside the original cusp coordinate disc
      $D_{\varepsilon_0}\cup\{p_0\}\subset B$, is disjoint from
      $\overline D_1\cup\overline D_2$.
\end{enumerate}
A number $\varepsilon_1$ satisfying these conditions is called an
\emph{auxiliary cutoff} for $\varepsilon$.
\end{definition}

\begin{lemma}
\label{lem:valid-cutoff-exists}
For every relatively compact parameter disc
$\Delta\Subset\mathcal A$, valid cusp cutoffs exist.  If $\varepsilon$ is
valid for $\Delta$ and $0<\varepsilon'<\varepsilon$, then
$\varepsilon'$ is valid for $\Delta$ with the same auxiliary cutoff.
\end{lemma}

\begin{proposition}
\label{prop:joint-cusp-action}
For every $\lambda\in\Z^2$, the map
\begin{equation}
\label{eq:Psi-action}
 \Psi_\lambda(y,a)
  =\bigl(c_{a,\lambda}(q(y))\cdot\Phi_\lambda(y),a\bigr)
\end{equation}
is a biholomorphism of $Y_\varepsilon\times\Delta$. The dependence on
$(y,a)$ is holomorphic, and
\[
 \Psi_\lambda\Psi_\mu=\Psi_{\lambda+\mu}.
\]
On the dense torus,
\begin{equation}
\label{eq:Psi-dense}
 \Psi_\lambda(x,q,a)
 =\bigl(c_{a,\lambda}(q)q^{B_0\lambda}x,q,a\bigr).
\end{equation}
\end{proposition}

\begin{lemma}
\label{lem:uniform-invertibility}
For the radius $\varepsilon$ chosen in \eqref{eq:epsilon-choice}, there is a
constant $K>0$ such that
\[
 \|B_{q,a}\|+\|B_{q,a}^{-1}\|\le K
\]
for every $0<|q|<\varepsilon$ and every $a\in\overline\Delta$.
\end{lemma}

\begin{lemma}
\label{lem:log-bound}
Let $K\subset Y_\varepsilon$ be compact.  There exists $M_K>0$ such that
\[
 \|y(x,q)\|\le M_K
\]
for every $(x,q)\in K$ lying in the dense torus with $q\ne0$.
\end{lemma}

\begin{proposition}
\label{prop:cusp-free}
The $\Z^2$-action \eqref{eq:Psi-action} on
$Y_\varepsilon\times\Delta$ is free.
\end{proposition}

\begin{proposition}
\label{prop:cusp-proper-discontinuous}
The $\Z^2$-action on $Y_\varepsilon\times\Delta$ is properly discontinuous.
\end{proposition}

\begin{lemma}
\label{lem:bounded-region-compact}
If $K_y\subset\R^2$ is bounded and $0<r<\varepsilon$, then the closure in
$Y$ of
\[
 \mathcal S(K_y,r)=
 \{(x,q)\in(\C^*)^2\times\C^*:
       |q|\le r,\ y(x,q)\in K_y\}
\]
is compact.
\end{lemma}

\begin{proposition}
\label{prop:compact-fundamental}
Let $K\subset D_\varepsilon\times\Delta$ be compact.  There exists a compact
set
\[
 C_K\subset (q,a)^{-1}(K)\subset Y_\varepsilon\times\Delta
\]
meeting every $\Z^2$-orbit over $K$.
\end{proposition}

\begin{lemma}
\label{lem:toric-central-normalization}
Let
\[
 D_Y=q^{-1}(0)\subset Y.
\]
Then $D_Y$ is reduced, and its normalization is the disjoint union
\begin{equation}
\label{eq:DY-normalization}
 \nu_Y:\coprod_{v\in\Z^2}E_v\longrightarrow D_Y
\end{equation}
of its smooth irreducible toric components.

\end{lemma}

\begin{proposition}
\label{prop:lifted-central-quotient}
Fix $a\in\Delta$ and set
\[
 \widetilde D_Y=\coprod_{v\in\Z^2}E_v.
\]
The action of $\Z^2$ on $D_Y$ lifts to a free properly discontinuous action
by biholomorphisms on $\widetilde D_Y$.  Its analytic orbit space is
biholomorphic to $E_0$.
\end{proposition}

\begin{proposition}
\label{prop:cusp-gluing}
For the disc $D_0=D_\varepsilon$ and the smaller horodisc
$\mathcal H_{0,\varepsilon}$ defined in
\eqref{eq:smaller-horodisc}, Equation \eqref{eq:Eexp} descends to a jointly
holomorphic biholomorphism
\begin{equation}
\label{eq:G0}
 G_0:\mathcal J_\Delta|_{D_0^*\times\Delta}
 \xrightarrow{\ \cong\ }
 \mathcal N_{0,\Delta}|_{D_0^*\times\Delta}.
\end{equation}
\end{proposition}

\begin{lemma}
\label{lem:hausdorff-gluing}
The glued topological space $\mathfrak X_\Delta$ is Hausdorff and
second-countable.  The quotient charts determine a unique complex manifold
structure on it.
\end{lemma}

\begin{definition}
\label{def:intrinsic-Xa}
For $a\in\mathcal A$, let $(X_a,f_a)$ be the fibre pair obtained from any
relatively compact disc $\Delta\Subset\mathcal A$ containing $a$ and any
valid cusp cutoff, whose existence follows from
\cref{lem:valid-cutoff-exists}.  Proposition~\ref{prop:choice-independence}
identifies all such choices by canonical biholomorphisms over $B$ satisfying
the cocycle law.  We use $(X_a,f_a)$ for any fixed representative.
\end{definition}

\begin{corollary}
\label{cor:global-smooth-type}
For any two admissible parameters $a,a'\in\mathcal A$, the fixed-parameter
compactifications $X_a$ and $X_{a'}$ are diffeomorphic.
\end{corollary}

\begin{corollary}
\label{cor:sphere-type}
Every compact threefold $X_a$ in the admissible family is diffeomorphic
to $S^6$.
\end{corollary}

\begin{lemma}\label{nm:lem:algebraic-band-base}
There are fibre-preserving biholomorphisms
$\mathcal E_m^{\rm an}\simeq E_m^{\rm an}$, where $E_m$ is the
Weierstrass surface over $\mathbf A^1_z$
\begin{equation}
 E_3:\ y^2=4x^3-3zx-1,\qquad
 E_4:\ y^2=4x^3-3x-z^2,
 \label{nm:eq:realized-elliptic-surfaces}
\end{equation}
with its section at infinity included.  The complement of this section in
$E_m$ is the affine Danielewski surface $W_m$ displayed in
\eqref{nm:eq:base3} or \eqref{nm:eq:base4}, respectively.
\end{lemma}

\begin{proposition}\label{nm:prop:one-fibre-oka}
For every $a_*\in\cA$, the principal opens $Y_{m,A}$, the bands $Y_m$,
the cyclic covers $Q_{m,a_*}$, the two complements
$X_{a_*}\setminus S_{1,a_*}$ and $X_{a_*}\setminus S_{2,a_*}$, and
$X_{a_*}$ are Oka.
\end{proposition}

\begin{lemma}\label{lem:proper-character}
For finitely many reduced algebraic curves in $(\C^*)^2$, there is a
monomial $M(u,v)=u^rv^s$ whose restriction to the normalization of every
irreducible component is proper and nonconstant, and hence finite.
\end{lemma}

\begin{theorem}\label{thm:semistable-finite-punctures}
For $m=3,4$ and every finite subset $R\subset M_m$, the manifold
$M_m\setminus R$ is Oka.
\end{theorem}

\begin{theorem}\label{thm:axis-deletion}
The manifold $Y_m\setminus\mathfrak A_m$ is Oka.
\end{theorem}

\begin{corollary}\label{cor:exotic-projective-threefold}
For every $a\in\cA$ and $p\in X_a$, the blow-up
$\Bl_pX_a$ is an Oka complex manifold diffeomorphic to $\PP^3$, but it is
not biholomorphic to the standard projective threefold.
\end{corollary}

\begin{corollary}\label{cor:smooth-curve-oka1}
If $C\subset X_a$ is a smooth compact complex curve, possibly
disconnected, then $\operatorname{Bl}_C X_a$ is Oka--$1$.  The same holds
after any finite sequence of blow-ups along smooth centres.
\end{corollary}

